package com.configmonitor.app;
import org.junit.Test;import org.json.*;import static org.junit.Assert.*;
public class RebuildTest {
 @Test public void inheritedThreshold() throws Exception {JSONObject n=new JSONObject();for(int i=0;i<2;i++)assertFalse(Rules.apply(n,false,-1,1000,3));assertTrue(Rules.apply(n,false,-1,1000,3));}
 @Test public void overrideThreshold() throws Exception {JSONObject n=Parser.j("rules",Parser.j("failureLimit",2));assertFalse(Rules.apply(n,false,-1,1000,9));assertTrue(Rules.apply(n,false,-1,1000,9));}
 @Test public void countdownWhileChecking() throws Exception {assertEquals(12000,new Cadence(true,true,3,3,0,15000,20000).json(3000).getLong("remainingMs"));}
 @Test public void autoAddresses() throws Exception {assertEquals("ICMP",Parser.address("1.1.1.1","","AUTO").getString("method"));assertEquals("TCP",Parser.address("1.1.1.1:443","","AUTO").getString("method"));assertEquals("ICMP",Parser.address("2001:db8::1","","AUTO").getString("method"));assertEquals("TCP",Parser.address("[2001:db8::1]:443","","AUTO").getString("method"));assertEquals("HTTPS",Parser.address("example.com","","AUTO").getString("method"));}
 @Test(expected=IllegalArgumentException.class) public void invalidIp() throws Exception {Parser.address("999.1.1.1","","AUTO");}
 @Test public void aliasesAndPlain() throws Exception {for(String[] alias:new String[][]{{"raw","tcp"},{"websocket","ws"},{"mkcp","kcp"},{"splithttp","xhttp"}}){JSONObject s=Parser.stream(new java.util.HashMap<String,String>(){{put("type",alias[0]);put("security","plain");}},"example.com");assertEquals(alias[1],s.getString("network"));assertEquals("none",s.getString("security"));}}
 @Test public void trojanSecurity() throws Exception {assertEquals("none",Parser.parse("trojan://secret@example.com:443?security=none").getJSONObject("config").getJSONObject("streamSettings").getString("security"));assertEquals("tls",Parser.parse("trojan://secret@example.com:443").getJSONObject("config").getJSONObject("streamSettings").getString("security"));}
 @Test public void tcpHeaderArrays() throws Exception {java.util.Map<String,String> q=new java.util.HashMap<>();q.put("headerType","http");q.put("host","a.example,b.example");q.put("path","/a,/b");JSONObject request=Parser.stream(q,"example.com").getJSONObject("tcpSettings").getJSONObject("header").getJSONObject("request");assertEquals(2,request.getJSONArray("path").length());assertEquals(2,request.getJSONObject("headers").getJSONArray("Host").length());}
 @Test public void backupPreservesInheritance() throws Exception {JSONObject doc=Parser.j("format",1,"nodes",Parser.a(Parser.j("type","address","raw","https://example.com","name","Example","enabled",true)),"settings",Parser.j("failureLimit",12));Backups.Prepared restored=Backups.validate(doc);assertFalse(restored.nodes.get(0).has("rules"));assertEquals(12,restored.settings.getInt("failureLimit"));}
 @Test public void vmessKeepsHttpAndInsecure() throws Exception {JSONObject v=Parser.j("add","example.com","id","11111111-1111-4111-8111-111111111111","port",443,"net","tcp","type","http","host","a.example,b.example","path","/a,/b","tls","tls","allowInsecure",true);String raw="vmess://"+java.util.Base64.getEncoder().encodeToString(v.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));JSONObject stream=Parser.parse(raw).getJSONObject("config").getJSONObject("streamSettings");assertTrue(stream.getJSONObject("tlsSettings").getBoolean("allowInsecure"));assertEquals(2,stream.getJSONObject("tcpSettings").getJSONObject("header").getJSONObject("request").getJSONArray("path").length());}
}
